sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    // Add your code here
    var str = current.subject.toString();
    if (str.includes('FOLLOW UP') || str.includes('CTM Allocation pending')) {
        current.api_response_from_qtrack = 'Review and Amend';
        current.update();
    } else {
		//MSSRBXCE-926
		var childRecord = new GlideRecord('x_hsb11_hsbcmss_eh_aggregated_trade_email_queue');//query from child table
		childRecord.addQuery('trade_case', current.trade_case_number);
		childRecord.query();
		gs.info('look up record from child table where trade_case_number is '+ current.trade_case_number);
		if (childRecord.next()) {
			gs.info('Record found: parent=' + childRecord.getDisplayValue('parent'));
			var parentRecord = new GlideRecord('x_hsb11_hsbcmss_eh_parent_aggregated_trade_email_queue');
			parentRecord.addQuery('sys_id', childRecord.parent);
			parentRecord.query();
			gs.info('look up record from parent table where sys_id is '+ childRecord.parent);
			if (parentRecord.next()) {
				gs.info('Record found: number=' + parentRecord.number+' and parent_task_type='+parentRecord.parent_task_type);
				if (parentRecord.parent_task_type == 'Review and Amend') {
					current.api_response_from_qtrack = "Review and Amend";
					current.update();
				} else {
					current.api_response_from_qtrack = "Sent-Ready";
					current.update();
				}
			}
		}
    }
})(current, previous);
